package com.apiautomation.base;
import java.util.Properties;
public final class TestConfig {private TestConfig(){} public static String baseUrl(){String value=System.getProperty("base.url");if(value==null||value.isBlank())value=System.getenv().getOrDefault("BASE_URL","http://localhost:8080");return value;} public static String dbUrl(){return System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3307/api_testing_db?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC");} public static String dbUser(){return System.getenv().getOrDefault("DB_USERNAME","api_user");} public static String dbPassword(){return System.getenv().getOrDefault("DB_PASSWORD","change-me-local");} public static long apiThreshold(){return Long.getLong("api.threshold.ms",1000L);} public static long loginThreshold(){return Long.getLong("login.threshold.ms",1500L);} }
